app = FastAPI()

HIGGS_URL   = "http://localhost:8007/v1/audio/speech"

# ── Reference voice (charma) — embedded at build time ────────────────────────
CHARMA_REF_TEXT = (
    "Tiana ingin memasak dan memiliki restoran. "
    "Aku pernah mencicipi gambo enak sekali, agak pedas"
)
_charma_ref_audio: str = "data:audio/mpeg;base64,"

def _load_charma():
    log.info(f"charma voice ready: {len(_charma_ref_audio)} chars")

# ── Chunking ──────────────────────────────────────────────────────────────────
MAX_CHUNK   = 380   # soft limit; ~25s audio/chunk max — model attention fails above ~30s

# ── Join ─────────────────────────────────────────────────────────────────────
GAP_MS      = 150   # silence gap between chunks (ms) — natural inter-sentence pause

# ── Artifact trim (measured from actual vllm-omni raw audio at 24kHz) ────────
# BOS: ~880ms of pure silence before speech (RMS 14-40), no loud boom
# EOS: ~1080ms of silence after speech ends
# Max speech RMS observed: ~1851 (quiet-speech level)
BOS_ONSET_THRESH = 120   # RMS above this = speech has started. BOC delay-fill artifact is
                         # typically 50-100 RMS — threshold above that skips it entirely.
BOS_BUFFER_MS    = 80    # keep this much audio before detected speech onset (safety margin)
EOS_SEARCH_PCT   = 0.75  # start EOS search only in last 25% of audio (skips natural pauses)
EOS_SILENCE_MS   = 500   # 500ms continuous silence = EOS onset (natural pauses are <400ms)

# ── Post-processing ───────────────────────────────────────────────────────────
TARGET_DBFS = -18.0


# ── 1. Text chunking — sentence boundaries only ───────────────────────────────

def _word_split(text, max_len):
    """Last resort: split at word boundaries. Never splits mid-word."""
    words = text.split()
    chunks, cur = [], ""
    for w in words:
        if not cur:
            cur = w
        elif len(cur) + 1 + len(w) <= max_len:
            cur += " " + w
        else:
            chunks.append(cur)
            cur = w
    if cur:
        chunks.append(cur)
    return chunks


def split_into_chunks(text):
    """Split text at sentence boundaries (. ! ? newline).
    Chunks never start or end mid-sentence.
    Mid-word splits are forbidden; very long sentences get word-split as fallback.
    """
    # Strip emoji/symbols that vllm-omni can't speak meaningfully
    text = re.sub(r'[\U00010000-\U0010FFFF]', '', text)   # 4-byte emoji (🍽️ etc.)
    text = re.sub(r'[☀-➿⬀-⯿]', '', text)  # misc symbols
    text = re.sub(r'\s+', ' ', text).strip()
    if not text:
        return []

    # Split into sentences at: punctuation followed by whitespace, OR newlines
    sents = [s.strip() for s in re.split(r'(?<=[.!?…])\s+|\n+', text) if s.strip()]
    if not sents:
        return _word_split(text, MAX_CHUNK)

    chunks, cur = [], ""
    n = len(sents)

    for j, sent in enumerate(sents):
        if len(sent) > MAX_CHUNK:
            if cur: chunks.append(cur); cur = ""
            chunks.extend(_word_split(sent, MAX_CHUNK))
            continue

        if not cur:
            cur = sent
            continue

        fits = len(cur) + 1 + len(sent) <= MAX_CHUNK
        if fits:
            # Lookahead: if this sent would trail at chunk end AND is short, flush now
            # so it LEADS the next chunk (TTS skips short trailing sentences)
            next_sent = sents[j + 1] if j + 1 < n else None
            next_fits = (next_sent is not None and
                         len(cur) + 1 + len(sent) + 1 + len(next_sent) <= MAX_CHUNK)
            trailing = next_sent is None or not next_fits
            if trailing and len(sent) <= 50 and len(cur) >= 100:
                chunks.append(cur)
                cur = sent
            else:
                cur += "\n" + sent
        else:
            chunks.append(cur)
            cur = sent

    if cur:
        chunks.append(cur)

    return [c for c in chunks if c.strip()]


# ── WAV I/O ───────────────────────────────────────────────────────────────────

def wav_bytes_to_array(data):
    with wave.open(io.BytesIO(data)) as wf:
        framerate  = wf.getframerate()
        n_channels = wf.getnchannels()
        sampwidth  = wf.getsampwidth()
        frames     = wf.readframes(wf.getnframes())
    dtype = {1: np.int8, 2: np.int16, 4: np.int32}.get(sampwidth, np.int16)
    audio = np.frombuffer(frames, dtype=dtype)
    if n_channels > 1:
        audio = audio[::n_channels]   # keep left channel only
    return audio, framerate, n_channels, sampwidth


def array_to_wav_bytes(audio, framerate, n_channels=1, sampwidth=2):
    buf = io.BytesIO()
    with wave.open(buf, 'wb') as wf:
        wf.setnchannels(n_channels)
        wf.setsampwidth(sampwidth)
        wf.setframerate(framerate)
        wf.writeframes(audio.astype(np.int16).tobytes())
    return buf.getvalue()


# ── 2. Artifact trimmer ───────────────────────────────────────────────────────

def find_speech_onset(audio, framerate):
    """Scan forward through BOS silence to find where speech actually starts.
    Requires SUSTAIN_WINS consecutive windows above threshold to avoid triggering
    on the 40-280ms BOC delay-fill artifact that fires before real speech.
    Returns sample index to cut from (speech onset minus BOS_BUFFER_MS).
    """
    win_n        = max(int(framerate * 0.02), 1)          # 20ms window
    max_n        = min(int(framerate * 2.0), len(audio))  # search first 2s max
    buf_n        = int(framerate * BOS_BUFFER_MS / 1000)  # safety buffer before onset
    sustain_wins = 3                                       # need 3×20ms = 60ms sustained

    consec   = 0
    onset_i  = 0
    for i in range(0, max_n - win_n, win_n):
        rms = float(np.sqrt(np.mean(audio[i:i + win_n].astype(np.float64) ** 2)))
        if rms > BOS_ONSET_THRESH:
            if consec == 0:
                onset_i = i
            consec += 1
            if consec >= sustain_wins:
                return max(0, onset_i - buf_n)
        else:
            consec = 0

    return 0  # no sustained speech found — keep everything


def trim_chunk_audio(audio, framerate):
    """Remove vllm-omni BOS and EOS silence from one chunk.

    Structure measured from real vllm-omni output (24kHz):
      [BOS silence ~880ms, RMS 14-40] [SPEECH, max RMS ~1851] [EOS silence ~1080ms+]

    1. Dynamic BOS trim: scan forward for first window above BOS_ONSET_THRESH (60).
       Back up BOS_BUFFER_MS (80ms) so we don't clip the speech onset.
    2. EOS trim: search only the last (1-EOS_SEARCH_PCT)=25% of audio for
       EOS_SILENCE_MS (500ms) of continuous silence.  Natural speech pauses are
       <400ms and happen well before the 75% mark.
    """
    # --- BOS ---
    onset = find_speech_onset(audio, framerate)
    audio = audio[onset:]
    if len(audio) == 0:
        return audio

    # --- EOS ---
    af      = audio.astype(np.float64)
    win_n   = max(int(framerate * 0.02), 1)
    eos_n   = int(framerate * EOS_SILENCE_MS / 1000)
    start_n = int(len(af) * EOS_SEARCH_PCT)

    body_rms = float(np.sqrt(np.mean(af[:max(start_n, win_n)] ** 2)))
    if body_rms < 30:
        return audio  # essentially silent chunk — return as-is

    silence_thresh = body_rms * 0.12  # 12% of body RMS

    silent_run = 0
    eos_cut    = len(af)
    i = start_n
    while i + win_n <= len(af):
        rms = float(np.sqrt(np.mean(af[i:i + win_n] ** 2)))
        if rms < silence_thresh:
            silent_run += win_n
            if silent_run >= eos_n:
                eos_cut = i - silent_run + win_n
                break
        else:
            silent_run = 0
        i += win_n

    # EOC wind-down trim: the delay codebook generates ~240ms of incoherent artifact
    # immediately before the EOS silence. A fixed 280ms backward trim from the silence
    # boundary removes it reliably for all languages, voices, and content — no amplitude
    # heuristic needed. Cost: ~40ms of trailing speech tail (inaudible in practice).
    eos_cut = max(0, eos_cut - int(framerate * 0.32))

    return audio[:eos_cut]


# ── 3. Join ───────────────────────────────────────────────────────────────────

def join_with_gap(arrays, framerate):
    """Concatenate chunks with a silent gap for natural inter-sentence pauses.
    Each chunk already has a sine fade-in (applied in assemble_chunks) and
    non-last chunks get a cosine fade-out, so the silence gap transitions are
    smooth with no boom/click.
    """
    if len(arrays) == 1:
        return arrays[0].astype(np.float64)

    gap = np.zeros(int(framerate * GAP_MS / 1000))
    result = arrays[0].astype(np.float64)
    for nxt in arrays[1:]:
        result = np.concatenate([result, gap, nxt.astype(np.float64)])
    return result


# ── 4. Post-processing ────────────────────────────────────────────────────────

def rms_normalize(audio):
    rms = float(np.sqrt(np.mean(audio ** 2)))
    if rms < 1.0:
        return audio
    target = 32768.0 * (10.0 ** (TARGET_DBFS / 20.0))
    gain   = float(np.clip(target / rms, 0.1, 6.0))   # cap at 6x (was 8x) to avoid noise amplification
    return audio * gain


def post_process(audio_f64, framerate):
    return np.clip(rms_normalize(audio_f64), -32768, 32767).astype(np.int16)


# ── MP3 encoding ──────────────────────────────────────────────────────────────

def wav_to_mp3(wav_bytes, bitrate="128k"):
    import tempfile, os
    with tempfile.NamedTemporaryFile(suffix=".wav", delete=False) as f:
        f.write(wav_bytes)
        tmp_in = f.name
    tmp_out = tmp_in.replace(".wav", ".mp3")
    try:
        proc = subprocess.run(
            ["ffmpeg", "-y", "-i", tmp_in,
             "-codec:a", "libmp3lame", "-b:a", bitrate, tmp_out],
            capture_output=True
        )
        if proc.returncode != 0 or not os.path.exists(tmp_out):
            raise RuntimeError(f"ffmpeg failed: {proc.stderr[-200:]}")
        with open(tmp_out, "rb") as f:
            return f.read()
    finally:
        for p in (tmp_in, tmp_out):
            try: os.unlink(p)
            except: pass


# ── Assembly ──────────────────────────────────────────────────────────────────

def assemble_chunks(wav_chunks):
    valid = [c for c in wav_chunks if c]
    arrays, meta = [], None

    n_valid = len(valid)  # for last-chunk detection

    for i, chunk_bytes in enumerate(valid):
        audio, framerate, n_channels, sampwidth = wav_bytes_to_array(chunk_bytes)

        orig_dur = len(audio) / framerate
        audio    = trim_chunk_audio(audio, framerate)
        trim_dur = len(audio) / framerate
        log.info(f"chunk[{i}] {orig_dur:.1f}s -> {trim_dur:.1f}s  (trimmed {orig_dur-trim_dur:.2f}s)")

        if len(audio) == 0:
            log.warning(f"chunk[{i}] empty after trim — skipping")
            continue

        af = audio.astype(np.float64)

        # Equal-power fade-in (sine) — covers BOS_BUFFER_MS window; suppresses BOC artifact.
        fi_n = min(int(framerate * BOS_BUFFER_MS / 1000), len(af))
        af[:fi_n] *= np.sin(np.linspace(0.0, np.pi / 2, fi_n))

        # Fade-out on all chunks — smooth the tail before the silence gap (or final cut).
        is_last = (len(arrays) == n_valid - 1)
        fo_ms = 50 if is_last else 40  # 50ms on last, 40ms on intermediate
        fo_n = min(int(framerate * fo_ms / 1000), len(af))
        af[-fo_n:] *= np.cos(np.linspace(0.0, np.pi / 2, fo_n))

        arrays.append(np.clip(af, -32768, 32767).astype(np.int16))
        if meta is None:
            meta = (framerate, n_channels, sampwidth)

    if not arrays or meta is None:
        return b""

    framerate, n_channels, sampwidth = meta
    combined = post_process(join_with_gap(arrays, framerate), framerate)
    return array_to_wav_bytes(combined, framerate, n_channels)


# ── HTTP ──────────────────────────────────────────────────────────────────────

import logging, sys
logging.basicConfig(stream=sys.stdout, level=logging.INFO,
                    format="%(asctime)s [proxy] %(message)s")
log = logging.getLogger("proxy")


@app.on_event("startup")
async def startup():
    _load_charma()


def _max_tokens_for(text: str) -> int:
    # chars × 0.065s/char × 25fps × 8 codebooks × 1.5 safety margin, min 2000
    return max(2000, int(len(text) * 0.065 * 25 * 8 * 1.5))


async def gen_one(body, auth, idx, retries=3, retry_delay=2.0):
    text = body.get("input", "")
    body = {**body, "max_new_tokens": _max_tokens_for(text)}
    text_preview = text[:60].replace("\n", " ")
    for attempt in range(retries):
        try:
            async with httpx.AsyncClient(timeout=300) as client:
                r = await client.post(HIGGS_URL, json=body,
                                      headers={"Authorization": auth})
            if r.status_code == 200:
                log.info(f"chunk[{idx}] OK  {len(r.content)//1024}KB  '{text_preview}'")
                return r.content
            log.warning(f"chunk[{idx}] HTTP {r.status_code} attempt {attempt+1}  body={r.text[:120]}")
        except Exception as e:
            log.warning(f"chunk[{idx}] ERROR attempt {attempt+1}: {e}")
        if attempt < retries - 1:
            await asyncio.sleep(retry_delay * (attempt + 1))
    log.error(f"chunk[{idx}] FAILED all retries  '{text_preview}'")
    return None


@app.post("/v1/audio/speech")
async def audio_speech(request: Request):
    body = await request.json()
    auth = request.headers.get("Authorization", "")
    text = body.get("input", "")

    chunks = split_into_chunks(text)
    log.info(f"request: {len(text)} chars -> {len(chunks)} chunk(s): "
             + " | ".join(f'"{c[:40]}"' for c in chunks))

    base = {k: v for k, v in body.items() if k != "input"}
    base["model"]           = "bosonai/higgs-audio-v3-tts-4b"
    base["response_format"] = "wav"
    base["seed"]            = 42
    base["temperature"]     = base.get("temperature", 0.5)
    base["top_k"]           = base.get("top_k", 10)
    base["emotion"]         = base.get("emotion", "neutral")
    base["expressiveness"]  = base.get("expressiveness", 0.1)
    base["speed"]           = base.get("speed", 1.0)

    # Auto-inject charma ref_audio when client sends voice=ref_voice without ref_audio
    if base.get("voice") in ("ref_voice", "charma") and "ref_audio" not in base:
        if _charma_ref_audio:
            base["ref_audio"] = _charma_ref_audio
            base["ref_text"]  = CHARMA_REF_TEXT
            log.info("injecting charma ref_audio")
        else:
            base.pop("voice", None)
            log.warning("charma not loaded, proceeding without ref voice")

    sem = asyncio.Semaphore(2)
    async def gen_limited(chunk_text, idx):
        async with sem:
            return await gen_one({**base, "input": chunk_text}, auth, idx)
    results = await asyncio.gather(*[
        gen_limited(c, i) for i, c in enumerate(chunks)
    ])

    good = [r for r in results if r]
    log.info(f"chunks done: {len(good)}/{len(chunks)} succeeded")
    merged = assemble_chunks(good)
    if not merged:
        raise HTTPException(status_code=502, detail="All chunk requests failed")

    mp3 = wav_to_mp3(merged)
    log.info(f"mp3 ready: {len(mp3)//1024}KB")
    return Response(content=mp3, media_type="audio/mpeg")
